NOTE_FIX=[("«тэГЕзэ»","«тэГЭðэ»"),("«ЛЭзэ»","«ЛЭðэ»"),("We're: «вие»","We're: «уиэ»"),("«уэа а ю фром»","«уэа а ю фром», голос вниз")]
def fix(s,d):
    for dd,a,b in R:
        if (dd is None or dd==d) and a in s: s=s.replace(a,b)
    for a,b in NOTE_FIX: s=s.replace(a,b)
    return s
def walk(x,d):
    if isinstance(x,str): return fix(x,d)
    if isinstance(x,list): return [walk(y,d) for y in x]
    if isinstance(x,dict): return {k:walk(v,d) for k,v in x.items()}
    return x
for f in sorted(glob.glob("b*.json")):
    j=json.load(open(f))
    for d in list(j):
        if d in OV:
            for k,v in OV[d].items(): j[d][k]=v
        j[d]=walk(j[d],d)
    json.dump(j,open(f,"w"),ensure_ascii=False,indent=0)
for f in sorted(glob.glob("ai/*.json")):
    d=os.path.basename(f).split("-")[0]
    if d in OV and os.path.basename(f).endswith("am.json") and "am" in OV[d]: os.remove(f);continue
    json.dump(walk(json.load(open(f)),d),open(f,"w"),ensure_ascii=False,indent=2)
